#!/usr/bin/env node
/**
 * Renders the Mermaid diagrams generated by scripts/generate-diagrams.mjs:
 *
 *   npm run diagrams:svg
 *
 * The browser used by Puppeteer comes from MERMAID_BROWSER_PATH in .env. When
 * the variable is empty Puppeteer falls back to the browser it manages, so the
 * path of a machine is never hardcoded in the repository.
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const projectRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const envPath = join(projectRoot, '.env');

if (existsSync(envPath)) {
  process.loadEnvFile(envPath);
}

const browserPath = (process.env.MERMAID_BROWSER_PATH ?? '').trim();
const diagrams = ['der', 'mer'];

let configDir = null;
const extraArgs = [];

if (browserPath) {
  if (!existsSync(browserPath)) {
    throw new Error(`MERMAID_BROWSER_PATH in .env does not exist: ${browserPath}`);
  }

  configDir = mkdtempSync(join(tmpdir(), 'mermaid-config-'));
  const configFile = join(configDir, 'puppeteer.json');
  writeFileSync(
    configFile,
    `${JSON.stringify({ executablePath: browserPath, args: ['--no-sandbox'] }, null, 2)}\n`,
  );
  extraArgs.push('-p', configFile);
} else {
  console.log('MERMAID_BROWSER_PATH is empty: Puppeteer will use its own browser');
}

let failed = false;

try {
  for (const name of diagrams) {
    const input = join(projectRoot, 'docs', 'diagrams', `${name}.mmd`);
    const output = join(projectRoot, 'docs', 'diagrams', `${name}.svg`);

    // Windows ships npx.cmd, which cannot be executed without a shell: cmd.exe
    // is invoked explicitly instead of using `shell: true` (deprecated when
    // arguments are passed separately).
    const command = process.platform === 'win32' ? 'npx.cmd' : 'npx';
    const cliArgs = ['-y', '@mermaid-js/mermaid-cli', '-i', input, '-o', output, ...extraArgs];

    const result =
      process.platform === 'win32'
        ? spawnSync('cmd.exe', ['/d', '/c', command, ...cliArgs], { stdio: 'inherit' })
        : spawnSync(command, cliArgs, { stdio: 'inherit' });

    if (result.status !== 0) {
      failed = true;
      console.error(`Failed to render ${name}.mmd`);
    }
  }
} finally {
  if (configDir) rmSync(configDir, { recursive: true, force: true });
}

if (failed) process.exit(1);

console.log('Rendered docs/diagrams/der.svg and docs/diagrams/mer.svg');
